WITH races_2017 AS (
    SELECT raceId FROM races WHERE year = 2017
), races_2000 AS (
    SELECT raceId FROM races WHERE year = 2000
), races_2017_not_2000 AS (
    SELECT r.raceId FROM races_2017 r
    LEFT JOIN races_2000 r2 ON r.raceId = r2.raceId
    WHERE r2.raceId IS NULL
), pitstop_counts AS (
    SELECT raceId, COUNT(*) AS pit_stop_count
    FROM pitStops
    WHERE raceId IN (SELECT raceId FROM races_2017_not_2000)
    GROUP BY raceId
)
SELECT ROUND(AVG(pit_stop_count), 2) AS avg_pit_stops
FROM pitstop_counts;

WITH total_majors AS (
    SELECT COUNT(*) AS count FROM major
), majors_with_members AS (
    SELECT COUNT(DISTINCT link_to_major) AS count FROM member WHERE link_to_major IS NOT NULL
)
SELECT ROUND(
    100.0 * (total_majors.count - majors_with_members.count) / total_majors.count
, 2) AS percentage_majors_without_members
FROM total_majors, majors_with_members;

WITH green_skin_colours AS (
  SELECT id FROM colour WHERE colour = 'green'
),
green_skinned_heroes AS (
  SELECT id FROM superhero WHERE skin_colour_id IN (SELECT id FROM green_skin_colours)
)
SELECT ROUND(AVG(weight_kg), 1) AS average_weight_kg
FROM superhero
WHERE id IN (SELECT id FROM green_skinned_heroes) AND weight_kg IS NOT NULL;

