WITH proteinuria_cases AS (
  SELECT DISTINCT p.ID, strftime('%Y', p.Birthday) AS year_of_birth
  FROM Patient p
  JOIN Laboratory l ON p.ID = l.ID
  WHERE (
    (CAST(l."U-PRO" AS INTEGER) >= 300)
  )
)
SELECT AVG(1999 - CAST(year_of_birth AS INTEGER)) AS average_age_in_1999
FROM proteinuria_cases;

