WITH chlorine_atoms AS (
  SELECT atom_id FROM atom WHERE element = 'cl'
), bonded_atoms AS (
  SELECT atom_id2 AS bonded_atom_id FROM connected WHERE atom_id IN (SELECT atom_id FROM chlorine_atoms)
  UNION
  SELECT atom_id AS bonded_atom_id FROM connected WHERE atom_id2 IN (SELECT atom_id FROM chlorine_atoms)
)
SELECT COUNT(DISTINCT bonded_atom_id) AS count_bonded_atoms FROM bonded_atoms;
